import json, re, random, chess, time
rules = json.load(open("re.json"))
def run(fen):
    for p, r in rules: fen = re.sub(p, r, fen)
    return fen.split("\n")
def expected(fen):
    b = chess.Board(fen); s=set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        c=b.copy(); c.push(m); s.add(" ".join(c.fen().split(" ")[:-2]))
    return s
def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    ok = len(ours)==len(exp) and all(x in exp or x.rpartition(" ")[0]+" -" in exp for x in ours)
    if not ok:
        print("FAIL", fen); print(sorted(ours)); print(sorted(exp)); raise SystemExit
fen="<REDACTED_B64> w kq - 0 1"
print(run(fen))
random.seed(1); n=0; t=time.time()
for g in range(400):
    b=chess.Board()
    while not b.is_game_over() and b.ply()<200:
        if b.turn==chess.WHITE and b.legal_moves.count()>0:
            check(b.fen()); n+=1
        b.push(random.choice(list(b.legal_moves)))
print("ok", n, time.time()-t)
EOF
